void check(bool value,const char* message){if(!value)throw std::invalid_argument(message);}
uint32_t number(const std::string& s){uint32_t out=0;auto [end,error]=std::from_chars(s.data(),s.data()+s.size(),out);check(error==std::errc{}&&end==s.data()+s.size(),"invalid unsigned option");return out;}
void fresh(const std::filesystem::path& p){check(std::filesystem::symlink_status(p).type()==std::filesystem::file_type::not_found,"fresh output required");}
void write(const std::filesystem::path& path,const void* data,size_t bytes){fresh(path);int fd=::open(path.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_CLOEXEC,0666);check(fd>=0,"exclusive output creation failed");size_t at=0;while(at<bytes){auto size=::write(fd,static_cast<const char*>(data)+at,bytes-at);if(size<0&&errno==EINTR)continue;if(size<=0){::close(fd);throw std::runtime_error("output write failed");}at+=size_t(size);}check(::close(fd)==0,"output close failed");}
json summary(std::vector<double> values){std::sort(values.begin(),values.end());return {{"p50",values[values.size()/2]},{"p95",values[std::min(values.size()-1,values.size()*95/100)]},{"mean",std::accumulate(values.begin(),values.end(),0.)/values.size()}};}
