json metadata(const CaptureFrame& f){json imu=json::array();for(auto const& sample:f.imu_samples){std::array<uint32_t,3> a{},w{};for(unsigned i=0;i<3;++i){a[i]=std::bit_cast<uint32_t>(sample.acceleration_m_s2[i]);w[i]=std::bit_cast<uint32_t>(sample.angular_velocity_deg_s[i]);}imu.push_back({{"timestamp_ns",sample.timestamp_ns},{"acceleration_bits",a},{"angular_velocity_bits",w},{"temperature_bits",std::bit_cast<uint32_t>(sample.temperature_c)},{"sync",sample.sync}});}return {{"source_width",f.source_width},{"height",f.height},{"stride_bytes",f.stride_bytes},{"frame_id",f.frame_id},{"camera_timestamp_ns",f.camera_timestamp_ns},{"host_ingress_timestamp_ns",f.host_ingress_timestamp_ns},{"camera_clock_domain",f.camera_clock_domain},{"host_clock_domain",f.host_clock_domain},{"calibration_identity",f.calibration_identity},{"device_identity",f.device_identity},{"controls_json",f.controls_json},{"control_status",f.control_status},{"controls_timestamp_ns",f.controls_timestamp_ns},{"controls_clock_domain",f.controls_clock_domain},{"sensor_status",f.sensor_status},{"imu_clock_domain",f.imu_clock_domain},{"imu_association",f.imu_association},{"sensor_dropped_count",f.sensor_dropped_count},{"imu_samples",imu}};}
